const http = require('http');
const fs = require('fs');
function getJson(url){return new Promise((res,rej)=>{http.get(url,r=>{let b='';r.on('data',c=>b+=c);r.on('end',()=>res(JSON.parse(b)));}).on('error',rej);});}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{
  const targets = await getJson('http://127.0.0.1:9222/json');
  const page = targets.find(t=>t.type==='page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res,rej)=>{ws.onopen=res;ws.onerror=rej;});
  let id=0; const pending=new Map(); const requests=[]; const exceptions=[];
  ws.onmessage=m=>{const d=JSON.parse(m.data);
    if(d.id&&pending.has(d.id)){pending.get(d.id)(d);pending.delete(d.id);}
    else if(d.method==='Network.requestWillBeSent') requests.push(d.params.request.url);
    else if(d.method==='Runtime.exceptionThrown') exceptions.push(d.params.exceptionDetails.exception?.description);
  };
  const send=(method,params={})=>new Promise(res=>{const i=++id;pending.set(i,res);ws.send(JSON.stringify({id:i,method,params}));});
  const ev=async(expr)=>{const r=await send('Runtime.evaluate',{expression:expr,returnByValue:true});if(r.result.exceptionDetails)throw new Error(r.result.exceptionDetails.exception?.description||'eval x');return r.result.result.value;};
  await send('Runtime.enable'); await send('Page.enable'); await send('Network.enable');
  await send('Page.navigate',{url:'file:///home/dp/MyProjects/disc/.tmpwork/disc-pi-lak86kfu/run/index.html'});
  await sleep(1800);

  // открыть модалку
  await ev(`document.querySelector('[data-open-wizard]').click()`);
  await sleep(120);

  const drag = (elExpr, fromX, fromY, toX, toY, ptype) => ev(`(() => {
    const el = ${elExpr};
    const r = el.getBoundingClientRect();
    const sx = r.left + ${fromX}, sy = r.top + ${fromY};
    const ex = r.left + ${toX}, ey = r.top + ${toY};
    const o = (x,y)=>({bubbles:true,pointerId:9,pointerType:'${ptype}',isPrimary:true,button:0,buttons:1,clientX:x,clientY:y});
    el.dispatchEvent(new PointerEvent('pointerdown', o(sx,sy)));
    el.dispatchEvent(new PointerEvent('pointermove', o(sx+3,sy+3)));
    for(let i=1;i<=10;i++) el.dispatchEvent(new PointerEvent('pointermove', o(sx+3+(ex-sx-3)*i/10, sy+3+(ey-sy-3)*i/10)));
    el.dispatchEvent(new PointerEvent('pointerup', o(ex,ey)));
  })()`);

  // 1) touch по всему элементу НЕ должен тащить
  await drag(`document.querySelector('#draggable-list1 .disc-item')`, 5, 15, 5, 100, 'touch');
  const afterItemTouch = await ev(`[...document.querySelectorAll('#draggable-list1 .disc-item')].map(li=>li.dataset.type).join(',')`);
  console.log('after touch-drag by ITEM (expect unchanged):', afterItemTouch);

  // 2) touch за handle ДОЛЖЕН тащить
  await drag(`document.querySelector('#draggable-list1 .disc-item .disc-handle')`, 7, 14, 7, 72, 'touch');
  const afterHandleTouch = await ev(`[...document.querySelectorAll('#draggable-list1 .disc-item')].map(li=>li.dataset.type).join(',')`);
  console.log('after touch-drag by HANDLE:', afterHandleTouch);

  // 3) сетевые запросы (кроме file://)
  const external = requests.filter(u => !u.startsWith('file://') && !u.startsWith('ws://') && !u.startsWith('http://127.0.0.1'));
  console.log('NETWORK REQUESTS TOTAL:', requests.length, 'EXTERNAL:', external.length);
  if (external.length) console.log('EXTERNAL:', external);

  console.log('JS EXCEPTIONS:', exceptions.length, exceptions.slice(0,3));
  process.exit(0);
})().catch(e=>{console.error('ERR',e);process.exit(1);});
EOF
